import MathFin.Performance.PurgedCV

open MeasureTheory ProbabilityTheory
open scoped NNReal
open MathFin

/-- **After purging, test labels are independent of surviving training labels.** -/
theorem purged_cv_no_leakage_brownian_thm {ι κ Ω E E' : Type*} {mΩ : MeasurableSpace Ω}
    {P : Measure Ω} [MeasurableSpace E] [MeasurableSpace E'] {B : ℝ≥0 → Ω → ℝ}
    (hB : IsPreBrownianReal B P) {lo hi : ι → ℝ≥0} {lo' hi' : κ → ℝ≥0}
    (hspan : ∀ i, lo i ≤ hi i) (hspan' : ∀ j, lo' j ≤ hi' j) {L : ι → Ω → E}
    {L' : κ → Ω → E'} (hL : ∀ i, IsSpanLabel B (lo i) (hi i) (L i))
    (hL' : ∀ j, IsSpanLabel B (lo' j) (hi' j) (L' j)) {i : ι}
    (hret : ∀ j, ¬ overlapsTest lo hi lo' hi' i j) (j : κ) :
    IndepFun (L i) (L' j) P :=
  MathFin.indepFun_of_purged hB hspan hspan' hL hL' hret j
